          "type": "paragraph",
          "text": "Metacognitive Argument-Driven Inquiry (MADI) is an instructional model that integrates argument-driven inquiry with metacognitive regulation. It engages learners in investigating a guiding question, gathering evidence, constructing claims with reasoning, participating in peer discussion, and reflecting on their thinking process (Antonio & Prudente, 2021)."
