            "improved quality of summaries and student-generated questions",
            "stronger ability to identify and clarify confusion in a text",
            "better prediction and inference during reading",
            "more active participation in text discussion",
            "clearer evidence of comprehension monitoring",
            "improved transfer of strategies to unfamiliar texts.",
            "These indicators are consistent with the original studies, the 1994 review, and the recent Philippine evidence."
