      "Evidence From Related Studies": [
        {
          "type": "paragraph",
          "text": "Practice-framework support: Recent classroom resources define Collaborative Summarizing as a partner-based comprehension strategy where students closely read a section of complex text and negotiate a brief summary, often in 15 words or fewer. These sources support the instructional routine clearly, even though they are more practice-oriented than experimental (Pulitzer Center, 2024; California Authorizers Regional Center, 2022)."
        },
        {
          "type": "paragraph",
          "text": "Reading-comprehension evidence: Hong (2016) studied 96 seventh-grade students assigned to controlled reading, individual summarizing, and collaborative summarizing groups. The study reported that the two summarizing groups significantly outperformed the controlled reading group, although it found no significant overall difference between individual summarizing and collaborative summarizing. This is important because it supports summarizing as a useful reading strategy, while also showing that collaboration may not automatically outperform individual summarizing in every context."
        },
        {
          "type": "paragraph",
          "text": "Writing and language-development evidence: Sajedi (2014) investigated 86 first-year university students and reported that Collaborative Summary Writing had a positive effect on second-language development. This is useful especially for the writing and language side of the strategy, though it comes from an EFL higher-education context rather than a general K to 12 reading-comprehension classroom."
        },
        {
          "type": "paragraph",
          "text": "Related comprehension-strategy evidence: Collaborative Strategic Reading includes a summarizing component called Wrap Up, but a What Works Clearinghouse review of one well-implemented randomized study found no significant impact on Grade 5 reading comprehension in that specific trial. This is worth noting because it reminds us not to overclaim collaborative summarizing or related collaborative comprehension routines as automatically effective in all settings."
        },
        {
          "type": "paragraph",
          "text": "Philippine context: The reviewed sources did not include a strong Philippine empirical study using the exact label Collaborative Summarizing. The most honest local connection is contextual rather than direct: the MATATAG Reading and Literacy Curriculum Guide supports explicit and systematic reading instruction with feedback, which is consistent with teaching summarization routines carefully, but it does not itself validate this exact strategy by name."
        }
      ],
      "Data to Gather": [
        {
          "type": "list",
          "items": [
            "pretest and posttest scores in reading comprehension",
            "rubric scores for summary quality",
            "student summaries before and after intervention",
            "observation notes on partner discussion and participation",
            "error patterns in selecting main ideas and details",
            "oral language samples during summary negotiation",
            "follow-up writing tasks based on the same reading. These data are appropriate because the strategy aims to improve both comprehension and concise meaning-making through collaboration."
          ]
        }
      ],
      "Indicators of Success": [
        {
          "type": "list",
          "items": [
            "increased posttest mean score in reading comprehension",
            "stronger ability to identify the main idea",
            "better selection of relevant details",
            "clearer and more concise summaries",
            "improved student discussion about text meaning",
            "better transfer from reading to summary writing",
            "more active participation during text-based partner work. These indicators match the documented purposes of the strategy and the kinds of outcomes measured in the available studies."
          ]
        }
      ],
