            "The OSEP briefs describe Tier 1 as the universal level for most students, with Tier 2 and Tier 3 providing increasingly intensive intervention. One brief notes a common distribution in which about 80% of students are supported at Tier 1, about 15% at Tier 2, and about 5% at Tier 3, while also emphasizing that families should be engaged at all tiers.",
            "Another core feature is that intervention should enhance, not replace, effective core instruction. The briefs also stress that English learners with foundational reading difficulties may need instruction that addresses both basic reading skills and oral language, vocabulary, and comprehension. This is consistent with the IES practice guide for English learners, which recommends small-group instructional intervention for struggling learners and notes that foundational skills should be taught alongside language and comprehension support."
